//   Course Clips/ 8 - Storyline Stars/ 8 - Bowser's Trap/Bowser Key / layer 'Layer 1' / frame 1
void frame_2912_0(Activation& scope) {
    stop();
    scope["count"] = 0;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope["count"] > 3 && _root["Course"]["Char"]["air"] == false) {
            if (scope.self["box"]["hitTest"](_root["Course"]["Char"]["charClip"]["body"]) || scope.self["box"]["hitTest"]((_root["Course"]["Char"]["_x"] * _root["coursescale"] / 100) + _root["Course"]["_x"], ((_root["Course"]["Char"]["_y"] - 15) * _root["coursescale"] / 100) + _root["Course"]["_y"], true)) {
                if (strictNotEquals(_root[scope["key"]], true)) {
                    //
                    _root["Course"]["Char"]["attack"] = true;
                    _root["Course"]["Char"]["attackFrame"] = "Key";
                    _root["heldItemObtained"] = scope["key"];
                    _root["lastPlayinglevel"] = _root["Playinglevel"];
                    if (scope["key"] == "BowserKeyA") {
                        _root["LastItemGot"] = "BowserKey1";
                        //_root.heldItemMessage = "CONGRATULATIONS!/nYou have obtained the Bowser Key that unlocks the Basement of the Castle!";
                    }
                    if (scope["key"] == "BowserKeyB") {
                        _root["LastItemGot"] = "BowserKey2";
                        _root["heldItemMessage"] = "CONGRATULATIONS!" + scope["newline"] + "You have obtained the 2nd Bowser Key.  Now the Upper Rooms of the Castle are unlocked!";
                    }
                }
                if (scope["key"] == "BowserKeyA") {
                    _root["BowserKey1"] = true;
                }
                if (scope["key"] == "BowserKeyB") {
                    _root["BowserKey2"] = true;
                }
                //
                gotoAndStop(4);
            }
        } else {
            scope["count"]++;
        }
        return undefined;
    });
    if (scope["key"] == "BowserKeyA") {
        gotoAndStop(2);
    }
    if (scope["key"] == "BowserKeyB") {
        gotoAndStop(3);
    }
}

